export default defineComponent({
  async run({ steps, $ }) {
    const { email } = steps.trigger.event.body || {};
    if (!email) {
      await $.respond({ status: 400, body: { error: 'email is required' } });
      return $.flow.exit('missing email');
    }
    await $.respond({ status: 200, body: { ok: true } });
    return { email };
  },
});
